import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.action, 'RequestVote');
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('nX')).ok, false);
});

test('deliverAll elects n0', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('vote reply shape, and a refused vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const toN1 = (await h.inFlight()).find((m) => m.action === 'RequestVote' && m.from === 'n0' && m.to === 'n1')!;
  await h.deliver(toN1.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual({ from: reply.from, to: reply.to, data: reply.data }, { from: 'n1', to: 'n0', data: { term: 1, granted: false } });
  assert.deepEqual(await h.node('n1'), { role: 'candidate', term: 1, votedFor: 'n1' });
});

test('all three time out: at most one leader, in any order', async () => {
  for (let seed = 0; seed < 40; seed++) {
    const h = await createHost();
    for (const n of NODES) await h.timeout(n);
    let s = seed + 1;
    for (;;) {
      const msgs = await h.inFlight();
      if (!msgs.length) break;
      s = (s * 1103515245 + 12345) % 2147483648;
      await h.deliver(msgs[s % msgs.length].id);
    }
    const views = await Promise.all(NODES.map((n) => h.node(n)));
    assert.ok(views.filter((v) => v!.role === 'leader').length <= 1);
  }
});

test('one candidate, random order: elected', async () => {
  for (let seed = 0; seed < 20; seed++) {
    const h = await createHost();
    await h.timeout('n2');
    if (seed % 2) await h.timeout('n0');
    let s = seed + 7;
    for (;;) {
      const msgs = await h.inFlight();
      if (!msgs.length) break;
      s = (s * 1103515245 + 12345) % 2147483648;
      await h.deliver(msgs[s % msgs.length].id);
    }
    const views = await Promise.all(NODES.map((n) => h.node(n)));
    const leaders = views.filter((v) => v!.role === 'leader').length;
    assert.ok(leaders <= 1);
    if (seed % 2 === 0) assert.equal(leaders, 1);
  }
});

