import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.action, 'RequestVote');
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('nX')).ok, false);
});

test('deliverAll elects n0', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('leader announces; term-0 node joins without voting; candidate steps down', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  // n2 votes for n0, n0 leads
  const rv = (await h.inFlight()).find((m) => m.action === 'RequestVote' && m.from === 'n0' && m.to === 'n2')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply' && m.to === 'n0')!;
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const ann = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.equal(ann.length, 2);
  for (const m of ann) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  await h.deliver(ann.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n0' });
  await h.deliverAll();
  assert.equal((await h.node('n0'))!.role, 'leader');

  // a term-0 node that hears Leader first joins term 1 without voting
  const h2 = await createHost();
  await h2.timeout('n0');
  const rv1 = (await h2.inFlight()).find((m) => m.to === 'n1')!;
  await h2.deliver(rv1.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h2.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
});

test('giveUp: candidate becomes follower, keeps its vote, ignores replies, grants nothing', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('nX')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });

  // another node can still be elected, with the vote of a node that has not voted
  const h2 = await createHost();
  await h2.timeout('n0');
  await h2.giveUp('n0');
  await h2.timeout('n1');
  await h2.deliver((await h2.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!.id);
  await h2.deliverAll();
  assert.deepEqual(await h2.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n1' });
  assert.equal((await h2.node('n1'))!.role, 'leader');
});

